// single-item input: one call from the pipeline.
//
// The body is read from the webhook by name, not from $input. Settings sits
// between the two and a Set node in manual mode replaces the item, so $input
// here is the configuration and the request would be silently invisible - the
// workflow would quietly check the default list on every deploy.
const cfg = $('Settings').first().json;
const body = $('Deploy Hook').first().json.body || {};

// The pipeline sends the URLs it just deployed. Run by hand with no body, the
// Settings list stands in, so the workflow is testable without a pipeline.
let urls = Array.isArray(body.urls) && body.urls.length
  ? body.urls
  : String(cfg.urls || '').split(',');

urls = urls
  .map(u => String(u || '').trim())
  .filter(Boolean)
  .map(u => (u.indexOf('http') === 0 ? u : 'https://' + u))
  .slice(0, Math.max(1, Number(cfg.max_urls) || 20));

if (!urls.length) {
  throw new Error(
    'No URLs to check. Send {"urls": ["https://..."]} in the request body, or ' +
    'put a comma separated list in Settings.'
  );
}

// The Code sandbox has no URL class, so the origin is taken with a regex.
const m = urls[0].match(/^(https?:\/\/[^/]+)/);
const origin = m ? m[1] : '';

if (!origin) {
  throw new Error('Could not read a host out of "' + urls[0] + '".');
}

return [{
  json: {
    urls,
    origin,
    label: String(body.label || cfg.default_label || 'manual run'),
    robots_url: origin + '/robots.txt',
    sitemap_url: String(cfg.sitemap_url || '').trim() || origin + '/sitemap.xml',
  },
}];

// One verdict per URL. Everything here is a deploy blocker or a warning, and
// the difference matters more than the checks do: a gate that fires on things
// nobody would roll back for is a gate somebody deletes.
const cfg = $('Settings').first().json;
const urls = $('Pick The URLs To Check').first().json.urls;

// With responseFormat "text" and fullResponse on, the payload arrives under
// `data`, not `body` - the full response object is {data, headers, statusCode,
// statusMessage}. Reading `body` gives undefined, every HTML check silently
// finds nothing, and the run is green with a clean report. Measured live on
// 2026-09-02; the first run of this workflow reported "not in the sitemap" for
// two URLs that were in it, because the XML was never read at all.
function bodyOf(x) {
  if (typeof x.data === 'string') return x.data;
  if (typeof x.body === 'string') return x.body;
  return '';
}

function norm(u) {
  return String(u || '')
    .trim()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/+$/, '')
    .replace(/[?#].*$/, '')
    .toLowerCase();
}

function attr(tag, name) {
  const m = String(tag || '').match(
    new RegExp(name + '\\s*=\\s*["\\\']([^"\\\']*)["\\\']', 'i')
  );
  return m ? m[1] : '';
}

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i += 1) {
  const res = items[i].json || {};
  const url = urls[i] || res.url || '';
  const status = Number(res.statusCode) || 0;
  const headers = res.headers || {};
  const html = bodyOf(res);

  const fail = [];
  const warn = [];

  // Header names arrive lower-cased from the node, but a value can be either
  // a string or an array when the server sent it twice.
  const xrt = []
    .concat(headers['x-robots-tag'] || [])
    .join(', ')
    .toLowerCase();

  const robotsMetaTag = (html.match(
    /<meta[^>]+name\s*=\s*["\'](?:robots|googlebot)["\'][^>]*>/i
  ) || [''])[0];
  const metaRobots = attr(robotsMetaTag, 'content').toLowerCase();

  if (status === 0) {
    fail.push('the request did not complete at all');
  } else if (status >= 300 && status < 400) {
    const to = [].concat(headers.location || []).join('');
    // A redirect that only adds or drops a trailing slash, a scheme or a www
    // is how most servers normalise a URL, and failing a deploy for it means
    // failing every deploy. docs.n8n.io/hosting/ answers 302 to
    // docs.n8n.io/hosting; that is a warning, not an incident.
    if (to && norm(to) === norm(url)) {
      warn.push('answers ' + status + ' to ' + to +
        ' - the same URL normalised, so link to the target directly');
    } else {
      fail.push('answers ' + status + (to ? ' to ' + to : '') +
        ' - the URL that was deployed is not the URL that serves');
    }
  } else if (status === 401 || status === 403) {
    // Not a failure. A fresh environment behind basic auth answers exactly
    // like a broken page, and so do reddit, medium and stackoverflow.
    warn.push('answers ' + status + ' - a login wall, a WAF, or genuinely gone');
  } else if (status >= 400) {
    fail.push('answers ' + status);
  }

  // The header is the one an HTML parser cannot see, and on a PDF or a feed it
  // is the only place a noindex can live at all. Its value is read rather than
  // its presence: n8n.io serves x-robots-tag: index, follow on a 404.
  if (xrt.indexOf('noindex') >= 0) {
    fail.push('the X-Robots-Tag header says noindex (' + xrt.slice(0, 80) + ')');
  } else if (xrt.indexOf('none') >= 0) {
    fail.push('the X-Robots-Tag header says none, which means noindex, nofollow');
  }

  if (metaRobots.indexOf('noindex') >= 0 || metaRobots.indexOf('none') >= 0) {
    fail.push('the robots meta tag says ' + metaRobots);
  }

  if (status === 200 && html) {
    const canonTag = (html.match(
      /<link[^>]+rel\s*=\s*["\']canonical["\'][^>]*>/i
    ) || [''])[0];
    const canon = attr(canonTag, 'href');

    if (!canon) {
      warn.push('no canonical link');
    } else if (norm(canon) !== norm(url)) {
      fail.push('canonical points at ' + canon + ', not at itself');
    }

    const title = (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1];
    if (!title || !title.trim()) fail.push('no title');

    if (!/<h1[\s>]/i.test(html)) warn.push('no h1');

    const bodyLen = html.length;
    if (bodyLen < Number(cfg.min_html_bytes || 1000)) {
      warn.push('only ' + bodyLen + ' bytes of HTML - a rendering regression ' +
        'looks exactly like this');
    }
  }

  out.push({
    json: {
      url,
      status,
      verdict: fail.length ? 'fail' : warn.length ? 'warn' : 'pass',
      fail,
      warn,
    },
  });
}

return out;

// single-item input: one robots.txt per site.
//
// Checked on its own because Disallow: / blocks a whole site and appears on no
// page. A deploy that ships the staging robots.txt is the classic version of
// this incident.
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;

// With responseFormat "text" and fullResponse on, the payload arrives under
// `data`, not `body` - the full response object is {data, headers, statusCode,
// statusMessage}. Reading `body` gives undefined, every HTML check silently
// finds nothing, and the run is green with a clean report. Measured live on
// 2026-09-02; the first run of this workflow reported "not in the sitemap" for
// two URLs that were in it, because the XML was never read at all.
function bodyOf(x) {
  if (typeof x.data === 'string') return x.data;
  if (typeof x.body === 'string') return x.body;
  return '';
}

const text = bodyOf(res);
const urls = $('Pick The URLs To Check').first().json.urls;

const fail = [];
const warn = [];

if (status !== 200) {
  // Not a failure. Plenty of sites serve no robots.txt at all and are indexed
  // perfectly well; a 404 here means "no rules", not "blocked".
  warn.push('robots.txt answered ' + (status || 'nothing'));
} else {
  // Only the rules that apply to every crawler. A Disallow under
  // User-agent: SemrushBot is somebody's bandwidth decision, not an incident.
  const lines = text.split(/\r?\n/).map(l => l.replace(/#.*$/, '').trim());
  let inStar = false;
  const disallow = [];

  for (const line of lines) {
    const ua = line.match(/^user-agent\s*:\s*(.+)$/i);
    if (ua) {
      inStar = ua[1].trim() === '*';
      continue;
    }
    const d = line.match(/^disallow\s*:\s*(.*)$/i);
    if (d && inStar) disallow.push(d[1].trim());
  }

  if (disallow.indexOf('/') >= 0) {
    fail.push('robots.txt has "Disallow: /" for every crawler - the whole ' +
      'site is blocked');
  }

  for (const u of urls) {
    const path = (u.match(/^https?:\/\/[^/]+(\/.*)$/) || [])[1] || '/';
    for (const rule of disallow) {
      if (rule && rule !== '/' && path.indexOf(rule) === 0) {
        fail.push('robots.txt blocks ' + path + ' with "Disallow: ' + rule + '"');
        break;
      }
    }
  }
}

return [{ json: { source: 'robots', status, fail, warn } }];

// single-item input: one sitemap per site.
//
// The mildest of the three checks on purpose. A URL missing from the sitemap
// is not a reason to roll a deploy back - it is a reason to look before the
// next one.
const res = $input.first().json || {};
const status = Number(res.statusCode) || 0;

// With responseFormat "text" and fullResponse on, the payload arrives under
// `data`, not `body` - the full response object is {data, headers, statusCode,
// statusMessage}. Reading `body` gives undefined, every HTML check silently
// finds nothing, and the run is green with a clean report. Measured live on
// 2026-09-02; the first run of this workflow reported "not in the sitemap" for
// two URLs that were in it, because the XML was never read at all.
function bodyOf(x) {
  if (typeof x.data === 'string') return x.data;
  if (typeof x.body === 'string') return x.body;
  return '';
}

const xml = bodyOf(res);
const urls = $('Pick The URLs To Check').first().json.urls;

const warn = [];

function norm(u) {
  return String(u || '').trim()
    .replace(/^https?:\/\//, '').replace(/^www\./, '')
    .replace(/\/+$/, '').replace(/[?#].*$/, '').toLowerCase();
}

if (status !== 200) {
  warn.push('the sitemap answered ' + (status || 'nothing'));
} else {
  const locs = [];
  for (const m of xml.matchAll(/<loc>([\s\S]*?)<\/loc>/gi)) {
    locs.push(norm(m[1]));
  }

  // A <sitemapindex> lists other sitemaps rather than pages, so none of the
  // deployed URLs will be in it and every one of them would read as missing.
  const isIndex = /<sitemapindex/i.test(xml);

  if (isIndex) {
    warn.push('the sitemap is an index of ' + locs.length + ' other sitemaps, ' +
      'so the URLs were not looked for');
  } else {
    const absent = urls.filter(u => locs.indexOf(norm(u)) < 0);
    if (absent.length) {
      warn.push(absent.length + ' of ' + urls.length +
        ' checked URLs are not in the sitemap: ' +
        absent.slice(0, 5).join(', '));
    }
  }
}

return [{ json: { source: 'sitemap', status, fail: [], warn } }];

// The three checks arrive through the merge above and are read back by name,
// because append order is not a contract worth relying on.
const pages = $('Check Every Page').all().map(i => i.json);
const robots = $('Read robots.txt').first().json;
const sitemap = $('Read The Sitemap').first().json;
const head = $('Pick The URLs To Check').first().json;

const failures = [];
const warnings = [];

for (const p of pages) {
  for (const f of p.fail) failures.push({ url: p.url, problem: f });
  for (const w of p.warn) warnings.push({ url: p.url, problem: w });
}
for (const f of robots.fail) failures.push({ url: head.robots_url, problem: f });
for (const w of robots.warn) warnings.push({ url: head.robots_url, problem: w });
for (const w of sitemap.warn) warnings.push({ url: head.sitemap_url, problem: w });

const verdict = failures.length ? 'failed' : warnings.length ? 'warned' : 'passed';

return [{
  json: {
    verdict,
    label: head.label,
    checked: pages.length,
    failures,
    warnings,
    failure_count: failures.length,
    warning_count: warnings.length,
    // What the pipeline reads. Everything else in here is for the humans.
    ok: !failures.length,
    summary:
      failures.length
        ? failures.length + ' blocking problem' +
          (failures.length === 1 ? '' : 's') + ' on ' + pages.length +
          (pages.length === 1 ? ' URL' : ' URLs')
        : warnings.length
        ? 'no blockers, ' + warnings.length + ' worth a look'
        : 'all ' + pages.length +
          (pages.length === 1 ? ' URL is' : ' URLs are') +
          ' indexable and self-canonical',
  },
}];

// single-item input: one verdict for the whole deploy.
const d = $input.first().json;
const lines = [];

lines.push(':octagonal_sign: *Deploy blocked* - ' + d.label);
lines.push(d.summary);
lines.push('');

for (const f of d.failures.slice(0, 15)) {
  lines.push('- ' + f.url + ': ' + f.problem);
}

if (d.warning_count) {
  lines.push('');
  lines.push('_Also, not blocking:_');
  for (const w of d.warnings.slice(0, 5)) {
    lines.push('- ' + w.url + ': ' + w.problem);
  }
}

return [{ json: Object.assign({}, d, { message: lines.join('\n').slice(0, 3800) }) }];

// single-item input: one verdict for the whole deploy.
const d = $input.first().json;
const lines = [];

lines.push(':warning: *Deploy went out with warnings* - ' + d.label);
lines.push(d.summary);
lines.push('');

for (const w of d.warnings.slice(0, 15)) {
  lines.push('- ' + w.url + ': ' + w.problem);
}

return [{ json: Object.assign({}, d, { message: lines.join('\n').slice(0, 3800) }) }];
